#include <stdio.h>

/**
 * @brief Calculates the length of a null-terminated string.
 *
 * This function iterates through the input string character by character,
 * incrementing a counter until the null terminator ('\0') is found.
 * The final count represents the length of the string.
 *
 * @param str The string (character array) whose length is to be calculated.
 * @return int The length of the string. Returns 0 if the string is empty or NULL.
 */
int custom_strlen(const char *str) {
    if (str == NULL) {
        return 0;
    }

    int length = 0;
    // Loop continues as long as the current character is not the null terminator
    while (str[length] != '\0') {
        length++;
    }

    return length;
}

